 const kinds=Object.keys(cues).concat('weather');cues.weather='风向环上有手动对准的刻痕。';
 function get(s,index){const id=typeof s==='string'?s:s?.id,row=rows[id]?.[index];if(!row)return null;const [kind,object,verb,observation]=row.split('|');return {kind,object,verb,observation,cue:cues[kind],index,id:'log:'+id+':'+index,siteId:id};}
 const reactions=new Map();
 function react(id){reactions.set(id,(reactions.get(id)||0)+1);}
 function revision(id){return reactions.get(id)||0;}
 function note(s,index,meaning){const c=get(s,index);if(!c)return meaning;return '我'+c.verb+'。'+c.observation;}
 function reflection(program){return reflections[program]||'先记下亲眼见到的。其余的，等下一处线索。';}
 function nearby(active,u,done){if(!active)return null;const r=active.deck.rooms.find(r=>Math.abs(u.x-r.x)<r.w/2&&Math.abs(u.y-r.y)<r.d/2);if(!r)return null;const n=active.deck.nodes.find(n=>n.kind==='log'&&n.room===r.id&&Math.hypot(u.x-n.x,u.y-n.y)<440&&!done(n));return n?{...get(active.structure,n.index),node:n}:null;}
 return {get,note,reflection,nearby,kinds,rows,react,revision};
